/// <summary>
/// MPJ_28395_Stock reservation - 21/07/2022
/// Class <c>METSalesOrderHoldClearController</c> to clear sales order holds
/// </summary>
class METSalesOrderHoldClearController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Creates new instance of <c>METSalesOrderHoldClearController</c>
/// </summary>
protected void new()
{
    super();
 
    this.parmClassName(classStr(METSalesOrderHoldClearService));
    this.parmMethodName(methodStr(METSalesOrderHoldClearService, processOperation));
 
    this.parmDialogCaption("@MET:AutoBatchClearHold");
}

/// <summary>
/// Sets the caption of the job
/// </summary>
/// <returns>Caption of the job</returns>
public ClassDescription caption()
{
    return "@MET:ClearOrderHold";
}

/// <summary>
/// Method which is run while calling the corresponding menu item
/// </summary>
/// <param name = "args">Arguments passed from the menu item</param>
public static void main(Args args)
{
    METSalesOrderHoldClearController controller;
 
    controller = new METSalesOrderHoldClearController();
    controller.startOperation();
}
